mapper.delete:
delete f,b,c,d,e from iot_event_source f
    left join iot_linkage a on f.id=a.event_source_id
    left join iot_linkage_item d on a.id=d.linkage_id and json_length(d.device_group_ids)!=0
    left join iot_linkage_condition b on a.id=b.linkage_id and b.linkage_item_id=d.id
    left join iot_linkage_action c on a.id=c.linkage_id and c.linkage_item_id = d.id
    left join iot_linkage_condition_item e on e.linkage_condition_id=b.id
where f.id in (

    #{eventSourceId}
);

mapper.select:
select p.* from iot_event_source a
    left join iot_product p on json_contains(a.product_ids, concat('', p.id))
where a.id=#{id} and p.status = #{status}

select dg.* from iot_event_source a
    inner join iot_device_group dg on json_contains(a.device_group_ids, concat('', dg.id))
where a.id = #{id}
